package com.example.mareasv7
import android.Manifest;import android.content.pm.PackageManager;import android.os.Bundle;import androidx.activity.*;import androidx.activity.compose.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.compose.foundation.*;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.pager.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.*;import androidx.compose.ui.graphics.Color;import androidx.compose.ui.platform.LocalContext;import androidx.compose.ui.unit.dp;import androidx.lifecycle.viewmodel.compose.viewModel;import com.example.mareasv7.ui.*
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{App()}}}
@Composable fun App(vm:VM= viewModel()){val s by vm.s.collectAsState();val permission=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){vm.load()};LaunchedEffect(Unit){permission.launch(Manifest.permission.ACCESS_FINE_LOCATION)};MaterialTheme{Surface(Modifier.fillMaxSize(),color=Bg){when(val q=s){State.Loading->Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){CircularProgressIndicator(color=Cyan)};is State.Error->Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Button(onClick=vm::load){Text(q.t)}};is State.Ready->Pager(q.d)}}}}
@Composable fun Pager(d:com.example.mareasv7.data.Data){val compact=LocalContext.current.packageManager.hasSystemFeature(PackageManager.FEATURE_WATCH);val count=8;val p= rememberPagerState(pageCount={count});Box(Modifier.fillMaxSize()){HorizontalPager(state=p,modifier=Modifier.fillMaxSize()){when(it){0->Home(d,compact);1->Tides(d,compact);2->Weather(d,compact);3->Wind(d,compact);4->Sea(d,compact);5->UV(d,compact);6->Beach(d,compact);else->Fishing(d,compact)}};Row(Modifier.align(Alignment.BottomCenter).padding(bottom=if(compact)10.dp else 14.dp),horizontalArrangement=Arrangement.spacedBy(6.dp)){repeat(count){Box(Modifier.size(if(it==p.currentPage)14.dp else 6.dp).background(if(it==p.currentPage)Cyan else Muted,androidx.compose.foundation.shape.CircleShape))}}}}
